import sys


def check_digit(digits):
    total = 0
    for i, ch in enumerate(digits):
        if i % 2 == 0:
            total += int(ch) * 3
        else:
            total += int(ch)
    return 10 - total % 10


def fmt(digits):
    return f"756.{digits[0:4]}.{digits[4:8]}.{digits[8:13]}"


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        clean = "".join(c for c in line if c.isdigit()).replace(" ", "")
        if len(clean) != 13 and len(clean) != 12:
            print("ERROR")
            continue
        if len(clean) == 13:
            if clean[:3] != "756":
                print("ERROR")
                continue
            if check_digit(clean[:12]) == int(clean[12]):
                print("VALID", fmt(clean))
            else:
                print("INVALID", check_digit(clean[:12]))
        elif len(clean) == 12:
            if clean[:3] != "756":
                print("ERROR")
                continue
            correct_digit = check_digit(clean)
            print("COMPLETE", fmt(clean + str(correct_digit)))
        else:
            print("ERROR")


if __name__ == "__main__":
    main()
